REPLACE = {'frontend/src/ConclusionGraph.css': {'before': 'b74d646d2c4c8f09be2fb72a4c52af35a7884ef64bfdf66a5fe271d3da559601', 'after': '/* Conclusion graph: glass stage cards on an animated flow, in the inspector. */\n\n.cg { margin-bottom: var(--space-5); padding-bottom: var(--space-4); border-bottom: 1px solid var(--separator); }\n.cg-head { display: flex; align-items: center; justify-content: space-between; gap: var(--space-2); margin-bottom: var(--space-3); }\n.cg-head h2 { font-family: var(--font-display); font-size: var(--font-size-md); font-weight: var(--font-weight-semibold);\n              letter-spacing: -0.012em; color: var(--label-1); }\n.cg-foot { margin: var(--space-2) 0 0; font-size: var(--font-size-xxs); line-height: 1.4; color: var(--label-3); }\n\n/* a sideways strip: glass cards left to right, snapping, fading at the edges */\n.cgx-scroll {\n  margin: 0 calc(-1 * var(--space-5)); padding: 6px var(--space-5) 12px;\n  overflow: auto; overscroll-behavior: contain; scroll-snap-type: x proximity; scroll-behavior: smooth;\n  scroll-padding-inline: var(--space-5); scrollbar-width: thin;\n  -webkit-mask-image: linear-gradient(to right, transparent 0, #000 var(--space-5), #000 calc(100% - var(--space-5)), transparent 100%);\n  mask-image: linear-gradient(to right, transparent 0, #000 var(--space-5), #000 calc(100% - var(--space-5)), transparent 100%);\n}\n.cgx-scroll:focus-visible { outline: 3px solid var(--accent-ring); outline-offset: -3px; border-radius: var(--radius-md); }\n.cgx-track { position: relative; display: flex; align-items: flex-start; gap: 30px; width: max-content; padding: 4px 2px; }\n.cgx-col { position: relative; z-index: 1; display: flex; flex-direction: column; gap: 22px; scroll-snap-align: start; }\n\n/* edges: a faint rail, a flowing dash and particles along it; the confirmed path glows */\n.cgx-edges { position: absolute; left: 0; top: 0; overflow: visible; pointer-events: none; z-index: 0; }\n.cgx-edge path { fill: none; stroke-linecap: round; }\n.cgx-edge-base { stroke-width: 1.6; stroke-dasharray: 100; stroke-dashoffset: 100;\n                 animation: cgx-draw 0.9s var(--ease-out) forwards; animation-delay: calc(0.25s + var(--k) * 0.12s); }\n.cgx-edge-flow { stroke-width: 1.6; stroke-dasharray: 3 9; animation: cgx-flow 1.1s linear infinite; opacity: 0.9; }\n.cgx-edge-glow { stroke-width: 6; opacity: 0.35; }\n\n/* the spine\'s stage nodes: a luminous core in a soft halo */\n.cgx-spine-dot { opacity: 0; animation: cgx-fade-in 0.4s ease forwards; animation-delay: calc(var(--k) * 0.12s); }\n.cgx-halo { fill: rgba(10, 132, 255, 0.16); stroke: rgba(90, 200, 250, 0.45); stroke-width: 1; }\n.cgx-core { fill: #0a84ff; filter: drop-shadow(0 0 4px #5ac8fa); }\n.cgx-spine-dot.is-done .cgx-halo { animation: cgx-pulse 2.8s ease-in-out infinite; transform-origin: center; transform-box: fill-box; }\n.cgx-spine-dot.is-abstain .cgx-halo { fill: rgba(255, 159, 10, 0.16); stroke: rgba(255, 196, 110, 0.55); }\n.cgx-spine-dot.is-abstain .cgx-core { fill: #ff9f0a; filter: drop-shadow(0 0 4px #ff9f0a); }\n.cgx-spine-dot.is-pending .cgx-halo { fill: none; stroke: var(--separator-strong); }\n.cgx-spine-dot.is-pending .cgx-core { fill: var(--label-3); filter: none; }\n@keyframes cgx-pulse { 0%, 100% { transform: scale(1); opacity: 1; } 50% { transform: scale(1.25); opacity: 0.55; } }\n.cgx-particle { opacity: 0; animation: cgx-fade-in 0.4s ease forwards; animation-delay: calc(1s + var(--k) * 0.12s); }\n.cgx-edge.is-done .cgx-edge-base, .cgx-edge.is-done .cgx-edge-glow { stroke: url(#cgx-done); }\n.cgx-edge.is-done .cgx-edge-flow { stroke: #bfe6ff; }\n.cgx-edge.is-done .cgx-particle { fill: #e6f6ff; filter: drop-shadow(0 0 3px #5ac8fa) drop-shadow(0 0 6px #0a84ff); }\n.cgx-edge.is-abstain .cgx-edge-base { stroke: rgba(255, 159, 10, 0.75); }\n.cgx-edge.is-abstain .cgx-edge-flow { stroke: #ffd08a; animation-duration: 1.8s; }\n.cgx-edge.is-abstain .cgx-particle { fill: #ffe2b0; filter: drop-shadow(0 0 3px #ff9f0a); }\n.cgx-edge.is-pending .cgx-edge-base { stroke: var(--separator-strong); stroke-dasharray: 2 4; animation: none; stroke-dashoffset: 0; }\n.cgx-edge.is-compare .cgx-edge-base { stroke: var(--label-3); stroke-dasharray: 2 3; animation: none; stroke-dashoffset: 0; }\n@keyframes cgx-draw { to { stroke-dashoffset: 0; } }\n@keyframes cgx-flow { to { stroke-dashoffset: -12; } }\n@keyframes cgx-fade-in { to { opacity: 1; } }\n\n/* glass stage cards */\n.cgx-node {\n  position: relative; display: flex; flex-direction: column; gap: 3px; width: 190px; min-height: 108px;\n  padding: 11px 12px 12px; border: 0; border-radius: 12px; text-align: left; cursor: default; font: inherit; color: var(--label-1);\n  background: linear-gradient(160deg, rgba(255, 255, 255, 0.07), rgba(255, 255, 255, 0.02)), var(--surface-raised);\n  -webkit-backdrop-filter: blur(14px) saturate(150%); backdrop-filter: blur(14px) saturate(150%);\n  box-shadow: 0 0 0 0.5px var(--separator-strong), 0 6px 18px rgba(0, 0, 0, 0.16), inset 0 1px 0 rgba(255, 255, 255, 0.08);\n  opacity: 0; transform: translateY(6px) scale(0.98);\n  animation: cgx-in 0.55s var(--ease-spring) forwards; animation-delay: calc(var(--k) * 0.12s);\n  transition: box-shadow var(--dur-base) ease, transform var(--dur-base) var(--ease-spring);\n}\n/* a gradient hairline around each card, brighter on the confirmed path */\n.cgx-node::before {\n  content: ""; position: absolute; inset: 0; border-radius: inherit; padding: 1px; pointer-events: none;\n  background: linear-gradient(140deg, rgba(255, 255, 255, 0.28), rgba(255, 255, 255, 0.02) 45%, rgba(255, 255, 255, 0.12));\n  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);\n  -webkit-mask-composite: xor; mask-composite: exclude;\n}\n.cgx-node.is-done { box-shadow: 0 0 0 0.5px rgba(10, 132, 255, 0.55), 0 0 22px rgba(10, 132, 255, 0.16), 0 6px 18px rgba(0, 0, 0, 0.16),\n                                inset 0 1px 0 rgba(255, 255, 255, 0.1); }\n.cgx-node.is-done::before { background: linear-gradient(140deg, rgba(90, 200, 250, 0.75), rgba(10, 132, 255, 0.1) 50%, rgba(90, 200, 250, 0.35)); }\n.cgx-node.is-abstain { box-shadow: 0 0 0 0.5px rgba(255, 159, 10, 0.6), 0 0 22px rgba(255, 159, 10, 0.14), 0 6px 18px rgba(0, 0, 0, 0.16); }\n.cgx-node.is-abstain::before { background: linear-gradient(140deg, rgba(255, 196, 110, 0.75), rgba(255, 159, 10, 0.08) 50%, rgba(255, 196, 110, 0.3)); }\n.cgx-node.is-compare { min-height: 0; background: transparent; -webkit-backdrop-filter: none; backdrop-filter: none;\n                       box-shadow: none; outline: 1px dashed var(--separator-strong); outline-offset: -1px; }\n.cgx-node.is-compare::before { display: none; }\n.cgx-node.is-pending { opacity: 0.6; }\n.cgx-node:hover { transform: translateY(-2px); }\n.cgx-node:active { transform: scale(0.98); }\n.cgx-node:focus-visible { outline: 3px solid var(--accent-ring); outline-offset: 2px; }\n\n/* the finding: filled, as the conclusion of the flow */\n.cgx-node.is-final.is-done { background: linear-gradient(150deg, #1f8fff, #0a6cff 60%, #0a54d6); color: #fff;\n  box-shadow: 0 0 0 0.5px rgba(160, 210, 255, 0.8), 0 0 30px rgba(10, 132, 255, 0.45), 0 8px 22px rgba(0, 0, 0, 0.25); }\n.cgx-node.is-final.is-done .cgx-title, .cgx-node.is-final.is-done .cgx-detail { color: rgba(255, 255, 255, 0.85); }\n.cgx-node.is-final.is-done .cgx-dot { background: rgba(255, 255, 255, 0.25); }\n.cgx-node.is-final.is-abstain { background: linear-gradient(150deg, rgba(255, 159, 10, 0.28), rgba(255, 159, 10, 0.12)); }\n\n.cgx-head { display: flex; align-items: center; gap: 7px; margin-bottom: 3px; }\n.cgx-dot { flex: none; min-width: 18px; height: 18px; padding: 0 4px; border-radius: 9px; display: grid; place-items: center;\n           font-family: var(--font-mono); font-size: 10px; font-weight: var(--font-weight-semibold); color: #fff; background: var(--accent);\n           box-shadow: 0 0 8px rgba(10, 132, 255, 0.55); }\n.cgx-node.is-abstain .cgx-dot { background: var(--status-orange); box-shadow: 0 0 8px rgba(255, 159, 10, 0.55); }\n.cgx-node.is-pending .cgx-dot, .cgx-node.is-compare .cgx-dot { background: var(--fill-pressed); color: var(--label-1); box-shadow: none; }\n.cgx-title { font-size: var(--font-size-xs); font-weight: var(--font-weight-semibold); letter-spacing: 0.01em; color: var(--label-2); }\n.cgx-value { font-size: var(--font-size-base); font-weight: var(--font-weight-medium); line-height: 1.3; overflow-wrap: anywhere; }\n.cgx-value.is-mono { font-family: var(--font-mono); font-variant-numeric: tabular-nums; }\n.cgx-detail { font-size: var(--font-size-xs); line-height: 1.35; color: var(--label-2); }\n@keyframes cgx-in { to { opacity: 1; transform: none; } }\n.cgx-node.is-pending { animation-name: cgx-in-dim; }\n@keyframes cgx-in-dim { to { opacity: 0.6; transform: none; } }\n\n/* the evidence card a node jumps to flashes once */\n/* the evidence card a node jumps to: a ring drawn OUTSIDE the card, with room around\n   it, above its sticky header - an edge shadow hugged the text and was clipped */\n.panel.cg-flash { position: relative; }\n.panel.cg-flash::after {\n  content: ""; position: absolute; inset: 6px -14px; z-index: 5; border-radius: 16px; pointer-events: none;\n  box-shadow: 0 0 0 1.5px rgba(10, 132, 255, 0.85), 0 0 26px rgba(10, 132, 255, 0.28), inset 0 0 18px rgba(10, 132, 255, 0.08);\n  animation: cg-card-flash 1.7s var(--ease-out) forwards;\n}\n@keyframes cg-card-flash { 0%, 35% { opacity: 1; } 100% { opacity: 0; } }\n\n@media (prefers-reduced-motion: reduce) {\n  .cgx-edge-flow, .cgx-particle { display: none; }\n  .cgx-spine-dot, .cgx-spine-dot .cgx-halo { animation: none; opacity: 1; }\n  .cgx-edge-base, .cgx-node { animation: none; opacity: 1; transform: none; stroke-dashoffset: 0; }\n}\n'}, 'frontend/src/ConclusionGraph.jsx': {'before': 'f16b6417ba2508a2835c29418694bf7abdac1eefc652efa46119d71363a872b1', 'after': 'import { useCallback, useLayoutEffect, useMemo, useRef, useState } from \'react\';\nimport \'./ConclusionGraph.css\';\n\n/**\n * Conclusion graph: how the finding was reached, stage by stage.\n *\n * Fully data-driven. buildStages() turns the case\'s artifacts into an ordered\n * list of stages - each with its state, what it found, a plain-language caption\n * of what it computes, and the evidence card it summarises - plus optional\n * branch stages (the proximity baseline hangs beneath forward replay as a\n * comparison). Layout and every edge are computed from the rendered nodes, so\n * nothing here fixes a node count or a position.\n *\n * Every value is a field an artifact already carries; nothing here computes\n * beyond formatting. The CONFIRMED path - stages that completed - glows and\n * carries particles; where the evidence stops (an abstention, an unseparated\n * ranking) the path turns amber; a stage whose artifact has not loaded is grey.\n */\n\nconst f3 = (x) => (typeof x === \'number\' ? x.toFixed(3) : \'—\');\n\nconst CAPTION = {\n  detection: \'Finds dark, smooth patches in the radar image that could be oil, and measures the outline.\',\n  filtering: \'Traces the slick backwards in time and keeps only vessels whose tracks passed through where it could have come from.\',\n  replay: \'For each remaining vessel, simulates oil released along its track and scores how well it recreates the observed slick.\',\n  baseline: \'The naive shortcut: whichever vessel was nearest the slick when the image was taken. Shown for comparison, not used.\',\n  fragility: \'Nudges the assumptions - currents, spreading, timing - to see whether the leading vessel stays on top.\',\n  finding: \'What the evidence supports: a lead for an analyst to follow up, never proof of responsibility.\',\n};\n\nfunction buildStages({ attribution, naive, report, detection, fragility }) {\n  const counts = report?.historical_filtering?.status_counts;\n  const top = attribution?.ranking?.[0];\n  const unknown = attribution?.unknown_source === true;\n  const disc = attribution?.discrimination;\n  const nearest = naive?.ranking?.[0];\n  const stages = [];\n\n  stages.push(!detection ? { id: \'detection\', title: \'Detection\', state: \'pending\' } : {\n    id: \'detection\', title: \'Detection\', state: detection.detected ? \'done\' : \'abstain\',\n    value: detection.detected ? `${detection.geometry.area_km2} km² slick` : \'No slick detected\',\n    detail: detection.detected ? `${detection.n_regions} region${detection.n_regions === 1 ? \'\' : \'s\'} · classical baseline detector` : null,\n  });\n  stages.push(!counts ? { id: \'filtering\', title: \'Historical filtering\', state: \'pending\' } : {\n    id: \'filtering\', title: \'Historical filtering\', state: \'done\',\n    value: `${counts.candidate ?? 0} candidates`,\n    detail: `${counts.unassessed ?? 0} unassessed · ${counts.excluded ?? 0} excluded by the backward origin envelope`,\n  });\n  const replay = !attribution ? { id: \'replay\', title: \'Forward replay\', state: \'pending\' } : {\n    id: \'replay\', title: \'Forward replay\', state: (unknown || disc?.discriminated === false) ? \'abstain\' : \'done\',\n    value: unknown ? \'No candidate cleared the fit gate\' : top?.vessel_key, mono: !unknown,\n    detail: unknown ? `best mean IoU ${f3(top?.mean_iou)} against a gate of ${attribution.abstention_iou_gate}`\n      : `mean IoU ${f3(top?.mean_iou)} · best under ${top?.ensemble_win_count}/${top?.n_ensemble} forcing variants`,\n    note: disc && disc.discriminated !== null && !unknown\n      ? (disc.discriminated ? `separated from the runner-up by a loss gap of ${disc.loss_gap}`\n        : `not separated from the runner-up: loss gap ${disc.loss_gap} is under ${disc.tolerance}`) : null,\n  };\n  if (nearest) {\n    replay.branches = [{\n      id: \'baseline\', title: \'Proximity baseline\', state: \'compare\', value: naive.top_candidate_id, mono: true,\n      detail: `${f3(nearest.distance_deg)}° from the slick — ${unknown ? \'replay names no one\'\n        : naive.top_candidate_id === attribution?.top_candidate_id ? \'the same vessel as replay\' : \'a different vessel from replay\'}`,\n    }];\n  }\n  stages.push(replay);\n  stages.push(!fragility ? { id: \'fragility\', title: \'Rank fragility\', state: \'pending\' } : {\n    id: \'fragility\', title: \'Rank fragility\', state: fragility.flip_found ? \'abstain\' : \'done\',\n    value: `${unknown ? \'Unnamed leader\' : \'Leader\'} held in ${Math.round(fragility.lead_retained_fraction * 100)}% of ${fragility.n_points_tested} perturbations`,\n    detail: fragility.flip_found && fragility.smallest_flip\n      ? `smallest change that flips it: ${Object.entries(fragility.smallest_flip.changed_axes)\n        .map(([k, v]) => `${k.replaceAll(\'_\', \' \')} ${v}`).join(\', \')} (magnitude ${fragility.smallest_flip.magnitude})`\n      : \'no tested perturbation changed the leader\',\n  });\n  stages.push(!attribution ? { id: \'finding\', title: \'Finding\', state: \'pending\', final: true } : {\n    id: \'finding\', title: \'Finding\', final: true, state: unknown ? \'abstain\' : \'done\',\n    value: unknown ? \'Unknown source\' : `${attribution.top_candidate_id} is physically consistent`,\n    detail: unknown ? \'no vessel is named; declining is the output\'\n      : `under the tested assumptions — an investigative lead, not proof of responsibility${disc?.discriminated === false ? \'; its ordering against the runner-up carries no weight\' : \'\'}`,\n  });\n  // what each stage summarises in the evidence column\n  const TARGET = { detection: \'Observed Scene\', filtering: \'Traffic Filtering and Provenance\', replay: \'Forward-Replay Ranking\',\n                   baseline: \'Proximity Baseline\', fragility: \'Rank Fragility\', finding: \'Case Finding\' };\n  const decorate = (s) => ({ ...s, caption: CAPTION[s.id], target: TARGET[s.id], branches: s.branches?.map(decorate) });\n  return stages.map(decorate);\n}\n\n/** An edge\'s state: glowing along the confirmed path, amber where the evidence stops. */\nconst edgeState = (from, to) => (to.state === \'compare\' ? \'compare\'\n  : from.state === \'pending\' || to.state === \'pending\' ? \'pending\'\n    : from.state === \'done\' && to.state === \'done\' ? \'done\' : \'abstain\');\n\nfunction jumpTo(title) {\n  const pane = document.querySelector(\'.finder-features\');\n  const h = [...(pane?.querySelectorAll(\'h2\') ?? [])].find((x) => x.textContent.trim() === title);\n  const card = h?.closest(\'.panel\') ?? h?.closest(\'section\');\n  if (!pane || !card) return;\n  const top = card.getBoundingClientRect().top - pane.getBoundingClientRect().top + pane.scrollTop - 12;\n  pane.scrollTo({ top, behavior: \'smooth\' });\n  card.classList.remove(\'cg-flash\'); void card.offsetWidth; card.classList.add(\'cg-flash\');\n  setTimeout(() => card.classList.remove(\'cg-flash\'), 1800);\n}\n\nfunction NodeCard({ s, index, register }) {\n  const ref = useRef(null);\n  useLayoutEffect(() => register(s.id, ref.current), [register, s.id]);\n  return (\n    <button type="button" ref={ref} className={`cgx-node is-${s.state}${s.final ? \' is-final\' : \'\'}${s.state === \'compare\' ? \' is-compare\' : \'\'}`}\n            style={{ \'--k\': index }} onClick={() => s.target && jumpTo(s.target)}\n            title={s.target ? `Open ${s.target}` : undefined}\n            aria-label={`${s.title}: ${s.value ?? \'not loaded\'}. ${s.caption ?? \'\'}`}>\n      <span className="cgx-head">\n        <span className="cgx-dot" aria-hidden="true">{s.state === \'compare\' ? \'vs\' : index + 1}</span>\n        <span className="cgx-title">{s.title}</span>\n      </span>\n      {s.state === \'pending\' ? <span className="cgx-detail">not loaded</span> : (\n        <>\n          <span className={`cgx-value${s.mono ? \' is-mono\' : \'\'}`}>{s.value}</span>\n          {s.detail && <span className="cgx-detail">{s.detail}</span>}\n          {s.note && <span className="cgx-detail">{s.note}</span>}\n        </>\n      )}\n    </button>\n  );\n}\n\nexport default function ConclusionGraph(props) {\n  const { attribution, naive, report, detection, fragility } = props;\n  // memoised on the artifacts themselves: the props object is new every render\n  const stages = useMemo(() => buildStages({ attribution, naive, report, detection, fragility }),\n                         [attribution, naive, report, detection, fragility]);\n  const track = useRef(null);\n  const nodes = useRef({});\n  const [edges, setEdges] = useState([]);\n  const [size, setSize] = useState({ w: 0, h: 0 });\n  const [viewH, setViewH] = useState(null);\n  const register = useCallback((id, el) => { nodes.current[id] = el; }, []);\n\n  // every edge from the rendered nodes: card to card left to right, and each\n  // branch hanging below its parent\n  const layout = useCallback(() => {\n    const t = track.current;\n    if (!t) return;\n    // Layout positions (offsetLeft/offsetTop), not getBoundingClientRect: the cards\'\n    // staggered entrance animation moves them with a transform, and measuring\n    // mid-animation left the connectors a few pixels out of level.\n    const box = (id) => {\n      const el = nodes.current[id];\n      if (!el) return null;\n      let l = 0, tp = 0;\n      for (let n = el; n && n !== t; n = n.offsetParent) { l += n.offsetLeft; tp += n.offsetTop; }\n      return { l, r: l + el.offsetWidth, t: tp, b: tp + el.offsetHeight, cx: l + el.offsetWidth / 2 };\n    };\n    const out = [];\n    stages.forEach((s, i) => {\n      const a = box(s.id);\n      if (!a) return;\n      const n = stages[i + 1] && box(stages[i + 1].id);\n      if (n) {\n        const y1 = a.t + 26, y2 = n.t + 26, dx = (n.l - a.r) / 2;\n        out.push({ id: `${s.id}-${stages[i + 1].id}`, state: edgeState(s, stages[i + 1]),\n                   d: `M${a.r},${y1} C${a.r + dx},${y1} ${n.l - dx},${y2} ${n.l},${y2}` });\n      }\n      (s.branches ?? []).forEach((br) => {\n        const b = box(br.id);\n        if (b) out.push({ id: `${s.id}-${br.id}`, state: edgeState(s, br),\n                          d: `M${a.cx},${a.b} C${a.cx},${a.b + 12} ${b.cx},${b.t - 12} ${b.cx},${b.t}` });\n      });\n    });\n    setEdges(out);\n    setSize({ w: t.scrollWidth, h: t.scrollHeight });\n    // the window fits the main row of cards; branches below are scrolled to\n    const main = Math.max(0, ...stages.map((st) => { const b = box(st.id); return b ? b.b : 0; }));\n    setViewH(Math.ceil(main) + 16);\n  }, [stages]);\n\n  useLayoutEffect(() => {\n    layout();\n    const ro = new ResizeObserver(layout);\n    if (track.current) ro.observe(track.current);\n    return () => ro.disconnect();\n  }, [layout]);\n\n  const confirmed = stages.filter((s) => s.state === \'done\').length;\n  return (\n    <section className="cg cgx" aria-label="How the finding was reached">\n      <div className="cg-head">\n        <h2>Conclusion Graph</h2>\n        <span className="tag">{confirmed} of {stages.length} stages confirmed</span>\n      </div>\n      <div className="cgx-scroll" tabIndex={0} role="group" style={viewH ? { height: viewH } : undefined}\n           aria-label="Pipeline stages, left to right; scroll sideways, and down for the comparison">\n        <div className="cgx-track" ref={track} role="list">\n          <svg className="cgx-edges" width={size.w} height={size.h} aria-hidden="true">\n            <defs>\n              <linearGradient id="cgx-done" x1="0" x2="1"><stop offset="0" stopColor="#0a84ff" /><stop offset="1" stopColor="#5ac8fa" /></linearGradient>\n              <filter id="cgx-glow" x="-20%" y="-100%" width="140%" height="300%"><feGaussianBlur stdDeviation="3" /></filter>\n            </defs>\n            {edges.map((e, i) => (\n              <g key={e.id} className={`cgx-edge is-${e.state}`} style={{ \'--k\': i }}>\n                {e.state === \'done\' && <path d={e.d} className="cgx-edge-glow" filter="url(#cgx-glow)" />}\n                <path d={e.d} className="cgx-edge-base" pathLength="100" />\n                {(e.state === \'done\' || e.state === \'abstain\') && <path d={e.d} className="cgx-edge-flow" />}\n                {(e.state === \'done\' || e.state === \'abstain\') && [0, 1].map((n) => (\n                  <circle key={n} r="2.3" className="cgx-particle">\n                    <animateMotion dur={e.state === \'done\' ? \'1.8s\' : \'2.8s\'} begin={`${n * (e.state === \'done\' ? 0.9 : 1.4) + i * 0.2}s`}\n                                   repeatCount="indefinite" path={e.d} />\n                  </circle>\n                ))}\n              </g>\n            ))}\n          </svg>\n          {stages.map((s, i) => (\n            <div className="cgx-col" key={s.id} role="listitem">\n              <NodeCard s={s} index={i} register={register} />\n              {(s.branches ?? []).map((br) => (\n                <NodeCard key={br.id} s={br} index={i} register={register} />\n              ))}\n            </div>\n          ))}\n        </div>\n      </div>\n      <p className="cg-foot">Click a stage to jump to its evidence. Scroll sideways for every stage, and down for the\n        proximity baseline. Replay and fragility are scored against the generator\'s slick mask, not the detected outline.</p>\n    </section>\n  );\n}\n'}}
CL_OLD = 'and was clipped, and is now a ring drawn outside the card, above its sticky header.\n'
CL_NEW = "and was clipped, and is now a ring drawn outside the card, above its sticky header.\n\n**Conclusion graph: level connectors, a cropped window, no hover caption.** Connectors\nwere measured while the cards' entrance animation still offset them, so they came out\nslightly slanted; they are now measured from layout positions and are exactly level.\nThe graph window is cropped to the main row of cards and scrolls both ways - the\nproximity baseline is scrolled down to rather than leaving empty space. The hover\ncaption is gone; each stage's description stays as its accessible label.\n"
read = lambda p: open(p, encoding="utf-8").read()
sha = lambda p: hashlib.sha256(open(p, "rb").read()).hexdigest()
writes, skipped = {}, 0
for p, v in REPLACE.items():
    if not os.path.exists(p): abort(f"{p} is missing")
    if read(p) == v["after"]: skipped += 1
    elif sha(p) == v["before"]: writes[p] = v["after"]
    else: abort(f"{p} is not the version this patch was written for; send its sha256")
cl = read("CHANGELOG.md")
if CL_NEW in cl: skipped += 1
elif cl.count(CL_OLD) == 1: writes["CHANGELOG.md"] = cl.replace(CL_OLD, CL_NEW, 1)
else: abort("CHANGELOG.md: the patch 19 entry this appends after was not found")
for p, text in writes.items():
    open(p, "w", encoding="utf-8").write(text)
print(f"patch 20: {len(writes)} files written, {skipped} already in place.")
